      "9-12": "A biografia de Sansão é um solene alerta sobre os perigos da autoconfiança e do comprometimento com o pecado. Apesar de suas fraquezas morais, Sansão figura na galeria dos heróis da fé (Hebreus 11:32) pela graça soberana de Deus, que ouviu sua oração de contrição no momento final de sua existência."
