      "3-5": "O profeta Elias subiu no alto do Monte Carmelo e desafiou os profetas dos ídolos de mentira. Eles gritaram o dia todo e nada aconteceu. Então Elias consertou o altar de Deus, colocou água para mostrar que não tinha truque e orou bem tranquilo. De repente... 'Fshhh!'. O fogo de Deus desceu do céu! O povo gritou feliz: 'Só o Senhor é Deus!'.",
      "6-8": "Elias desafiou oitocentos e cinquenta falsos profetas no Monte Carmelo para que a nação decidisse entre o Senhor e Baal. Enquanto os idólatras clamavam sem resposta, Elias restaurou o altar do Senhor, derramou doze cântaros de água sobre a lenha e fez uma oração de sessenta segundos pedindo que o coração do povo se convertesse. O fogo de Deus caiu, consumiu o holocausto, a lenha e a água, levando o povo a se prostrar em adoração.",
