      "6-8": "Na planície de Dura, Nabucodonosor ordenou adoração universal à sua imagem de ouro. Sadraque, Mesaque e Abede-Nego responderam com coragem histórica: 'O nosso Deus a quem servimos pode nos livrar da fornalha... e ainda que não livre, não serviremos a teus deuses'. Lançados no forno aquecido sete vezes mais, as chamas queimaram apenas suas cordas, e o rei viu o Filho de Deus andando com eles.",
      "9-12": "A narrativa de Daniel 3 proclama o ápice da fé incondicional ('mesmo que Ele não nos livre'). A manifestação do Quarto Homem é uma teofania/cristofania gloriosa: Deus não impede necessariamente que Seus servos entrem no sofrimento, mas entra no fogo com eles, revelando Sua presença confortadora e transformando a fornalha em púlpito de testemunho."
