      "6-8": "Por ocasião da Páscoa judaica, Jesus permaneceu no templo de Jerusalém. Após três dias de busca angustiada, Maria e José O encontraram no meio dos mestres da Lei, ouvindo-os e interrogando-os com espantosa inteligência. Ao ser questionado por Sua mãe, Jesus afirmou: 'Por que me procuráveis? Não sabeis que me convém tratar dos negócios de meu Pai?'.",
      "9-12": "Lucas 2:41-52 é o único vislumbre canônico da infância de Jesus. Revela Sua precoce consciência messiânica e Sua perfeita submissão aos pais terrenos em Nazaré. O versículo 52 apresenta o modelo quádruplo do desenvolvimento humano integral: intelectual (sabedoria), físico (estatura), espiritual (graça para com Deus) e social (graça para com os homens)."
