    "oracao": "Querido Jesus, como é lindo ver Tua obediência e amor pela casa do Pai! Ajuda-me a crescer como Tu cresceste: em sabedoria, em estatura e em graça diante de Deus e das pessoas. Em Teu Santo Nome, amém!",
