      "coracao": "Não desistir de orar por milagres e pela salvação da minha família e amigos.",
      "casa": "Cuidar e ser gentil com pessoas que não enxergam bem ou usam óculos fortes.",
      "escola": "Abrir os olhos do meu coração para enxergar as belezas e as bênçãos que Deus coloca à minha volta."
