      "9-12": "A passagem de Lucas 17 estabelece uma distinção essencial entre ser curado fisicamente e ser salvo integralmente. Os dez receberam a purificação da carne pela obediência inicial, mas apenas o samaritano grato experimentou a salvação da alma ao retornar para adorar a Fonte da graça. A gratidão é o selo autêntico da fé regenerada."
