      "9-12": "Marcos 10:13-16 subverte as convenções sociais da antiguidade greco-romana e judaica, onde crianças não possuíam status jurídico ou relevância social. Jesus coloca a infância como padrão de entrada no Reino: a fé infantil despretensiosa, receptiva e dependente é a única atitude pela qual o ser humano pode achegar-se ao Pai celestial."
