    "icon": "🌿👑",
    "objetivos_aprendizagem": [
      "Compreender o agir e o ensino de Jesus na narrativa de A entrada triunfal de Jesus.",
      "Identificar como a virtude bíblica de Hosana nas Alturas se aplica à vida diária.",
      "Memorizar e praticar o versículo-chave Mateus 21:9 com alegria e amor."
    ],
    "narrativa_por_idade": {
      "3-5": "Jesus estava chegando na grande cidade de Jerusalém! Ele pediu aos amigos para trazerem um jumentinho manso e subiu nele. Muitas pessoas e criancinhas ficaram radiantes de alegria! Cortaram ramos verdes de palmeiras, estenderam suas capas no caminho e cantaram bem alto: 'Hosana! Viva o Rei enviado por Deus!'. Jerusalém inteira ficou em festa!",
      "6-8": "Aproximando-se de Jerusalém pelo monte das Oliveiras, Jesus enviou discípulos para trazerem uma jumenta e seu jumentinho, cumprindo a profecia de Zacarias. Uma multidão imensa estendeu mantos pelo chão e cortou ramos de árvores, aclamando: 'Hosana ao Filho de Davi! Bendito o que vem em nome do Senhor! Hosana nas alturas!'. A cidade comoveu-se ao receber o Rei da Paz.",
      "9-12": "A Entrada Triunfal cumpre fielmente a profecia messiânica de Zacarias 9:9 ('Eis que o teu Rei virá a ti, justo e salvador, humilde e montado em um jumento'). Contrastando frontalmente com os imperadores romanos montados em corcéis de guerra, o Messias inaugura um reino pacífico, cujo senhorio se estabelece pela entrega sacrificial e pela redenção espiritual dos povos."
    },
    "versiculo": {
      "ref": "Mateus 21:9",
      "texto": "Hosana ao Filho de Davi! Bendito o que vem em nome do Senhor! Hosana nas alturas!"
    },
