      "6-8": "Levado ao monte Gólgota, Jesus foi crucificado entre dois malfeitores. Mesmo ultrajado, intercedeu pelos Seus algozes: 'Pai, perdoa-lhes, porque não sabem o que fazem'. Ao ladrão arrependido que suplicou por misericórdia, garantiu: 'Hoje estarás comigo no Paraíso'. À hora nona, o véu do santuário rasgou-se ao meio e Jesus bradou: 'Pai, nas tuas mãos entrego o meu espírito!'. O centurião romano, pasmo diante de Sua dignidade, glorificou a Deus confessando Sua justiça divina.",
      "9-12": "A crucificação constitui o clímax da teologia paulina e dos Evangelhos: a expiação substitutiva propiciatória. Cristo, o Justo pelos injustos, suportou a ira santa de Deus contra o pecado da humanidade (2 Coríntios 5:21). O rasgar do véu simboliza o término da Antiga Aliança sacrificial e o livre acesso de todo crente ao Santo dos Santos através do sangue de Jesus (Hebreus 10:19-20)."
