    "narrativa_por_idade": {
      "3-5": "Jesus chamou Seus discípulos para um encontro muito especial no topo de uma montanha ensolarada na Galileia. Olhando para eles com amor e poder, disse: 'Papai do Céu me deu todo o poder no céu e na terra! Agora é a vez de vocês: vão por todo o mundinho, contem as Minhas histórias de amor, ensinem as pessoas a obedecerem à Palavra de Deus e batizem os novos amigos. E escutem bem: Eu estarei juntinho de vocês todos os dias, até o fim dos tempos!'.",
      "6-8": "Os onze discípulos partiram para a montanha da Galileia designada por Jesus. Ao vê-Lo, adoraram-No. Jesus aproximou-Se e proclamou Sua autoridade suprema: 'É-me dado todo o poder no céu e na terra. Portanto, ide, fazei discípulos de todas as nações, batizando-os em nome do Pai, e do Filho, e do Espírito Santo; ensinando-os a guardar todas as coisas que vos tenho ordenado. E eis que eu estou convosco todos os dias, até a consumação dos séculos'.",
      "9-12": "A Grande Comissão (Mateus 28:18-20) é o mandato apostólico e missionário fundacional da Igreja. O mandamento principal é 'fazer discípulos' (matheteusate), operacionalizado por três particípios: indo, batizando no Nome trinitário e ensinando a guarda integral dos preceitos de Cristo. A autoridade universal de Cristo e Sua promessa de imanência perpétua ('estou convosco todos os dias') sustentam a expansão evangelística ininterrupta do Reino."
    },
