    "oracao": "Senhor Jesus glorioso, que alegria saber que Tu reinas no trono do Céu e intercedes por mim! Guarda o meu coraçãozinho limpo enquanto espero o Teu glorioso retorno. Dá-me poder do Teu Espírito para falar de Ti. Em Teu Santo Nome, amém!",
