      "6-8": "Cumprindo-se o dia de Pentecostes, estavam todos reunidos no mesmo lugar. De repente, veio do céu um som, como de um vento impetuoso, e encheu toda a casa onde estavam assentados. E viram línguas repartidas, como que de fogo, as quais pousaram sobre cada um deles. E todos foram cheios do Espírito Santo, passando a falar em outras línguas, segundo o Espírito lhes concedia que falassem. Judeus piedosos de todas as nações da terra ouviram as grandezas de Deus em suas línguas nativas.",
      "9-12": "O derramamento do Espírito Santo em Pentecostes (Atos 2) cumpre a promessa do profeta Joel (Joel 2:28-32) e a garantia outorgada por Jesus quanto ao Consolador (Parakletos - João 14:16). O batismo no Espírito Santo inaugura solenemente a era eclesiológica e missionária, revertendo a dispersão de Babel e unindo todos os povos no corpo de Cristo através do testemunho pentecostal."
