      "3-5": "Um viajante foi atacado na estrada e ficou caído no chão precisando de ajuda. Um sacerdote e depois um levita passaram por ali, mas não ajudaram e continuaram andando. Mas quando passou um homem samaritano, seu coração se encheu de carinho! Ele limpou os machucados do homem, colocou curativos com óleo, colocou-o no seu jumento e o levou a uma hospedaria, pagando tudo para cuidarem dele. Jesus disse: 'Vá e faça o mesmo!'.",
      "6-8": "Respondendo a um intérprete da lei que indagou quem era seu próximo, Jesus contou a parábola do homem assaltado entre Jerusalém e Jericó. Ignorado por um sacerdote e por um levita, foi socorrido por um samaritano que, movido de íntima compaixão, tratou suas feridas com azeite e vinho, levou-o a uma estalagem e arcou com todas as despesas. Jesus concluiu: 'Vai, e faze da mesma maneira'.",
      "9-12": "A Parábola do Bom Samaritano desmantela os limites étnicos e religiosos do amor da aliança. O samaritano, historicamente marginalizado pelos judeus, encarna o imperativo ético da misericórdia sacrificial (hesed). Jesus reconfigura a questão de 'quem é meu próximo' para 'como me torno o próximo daqueles que sofrem', revelando que o amor genuíno a Deus expressa-se necessariamente em solidariedade prática."
