      "6-8": "Ao ser criticado por acolher cobradores de impostos e pecadores, Jesus proferiu a parábola: que homem dentre vós, tendo cem ovelhas e perdendo uma, não deixa as noventa e nove no deserto e vai atrás da perdida até encontrá-la? E achando-a, põe-na jubiloso sobre os ombros e convoca os amigos para celebrar. Assim haverá mais júbilo no céu por um pecador arrependido do que por noventa e nove justos.",
      "9-12": "A Parábola da Ovelha Perdida (Lucas 15) revela o coração soteriológico de Deus: a busca ativa, diligente e afetuosa pelo ser humano desamparado. A imagem do pastor carregando a ovelha nos ombros ilustra a graça preveniente e o resgate operado por Cristo, culminando na liturgia celestial da festa angelical pela reconciliação do pecador."
