      "9-12": "A Parábola do Pai Misericordioso (comumente dita do Filho Pródigo) é o ápice do Evangelho lucano da graça. Retrata Deus Pai quebrando as convenções patriarcais orientais (um ancião não corria em público) para demonstrar graça soberana e escandalosa. O conflito com o irmão mais velho adverte contra o legalismo farisaico, afirmando que a redenção é dom paterno concedido pela justificação, e não mérito acumulado."
