    "oracao": "Senhor Deus, misericordioso e bom, obrigado por perdoares todos os meus pecados por amor de Jesus! Limpa o meu coração de toda mágoa. Ensina-me a perdoar meus amigos com generosidade e a viver em paz com todos. Em nome de Jesus, amém!",
