    "oracao": "Senhor Deus, Pai de justiça e compaixão, ensina-me a orar sempre e nunca desanimar! Obrigado porque Tu não és como um juiz duro, mas és o meu Pai que me escuta dia e noite. Dá-me fé firme para esperar no Teu tempo. Em nome de Jesus, amém!",
