      "6-8": "Interrogado por um legista fariseu acerca de qual seria o grande mandamento na Lei, Jesus articulou a essência da Revelação integrando o Shemá de Deuteronômio 6:5 e Levítico 19:18. Proclamou: 'Amarás o Senhor teu Deus de todo o teu coração, de toda a tua alma e de todo o teu entendimento. Este é o primeiro e grande mandamento. E o segundo, semelhante a este, é: Amarás o teu próximo como a ti mesmo. Destes dois mandamentos dependem toda a lei e os profetas'.",
      "9-12": "A resposta de Jesus em Mateus 22:34-40 condensa a totalidade do cânon veterotestamentário na primazia do ágape. A devoção monoteísta vertical a Yahweh não existe em isolamento pietista; ela se valida e encarna horizontalmente no amor sacrificial ao próximo. Amor não é mero sentimento efêmero, mas aliança volitiva total que orienta afetos, intelecto e conduta moral sob o senhorio de Deus."
