      "6-8": "O apóstolo João ensina que todo aquele que ama é nascido de Deus e conhece a Deus, pois Deus é amor. Nisto se manifestou o amor de Deus para conosco: em haver Deus enviado Seu Filho unigênito ao mundo para vivermos por meio Dele. Nisto consiste o amor: não em que nós tenhamos amado a Deus, mas em que Ele nos amou e enviou Seu Filho como propiciação pelos nossos pecados.",
      "9-12": "1 João 4 estabelece o fundamento ontológico da ética cristã: o amor (ágape) não é mero predicado divino, mas a própria essência do caráter de Deus expressa trinitariamente. O amor cristão é derivativo e responsivo à iniciativa graciosa do Pai manifestada na encarnação e morte expiatória do Filho, capacitando a comunidade da aliança a ser ícone visível do Deus invisível."
