    "oracao": "Senhor Jesus, manso e bondoso de coração, molda as minhas atitudes! Que a minha boca profira palavras doces e que as minhas mãos estejam prontas para ajudar. Faz de mim um canal da Tua bondade e gentileza para com todos. Em Teu Santo Nome, amém!",
