      "6-8": "Paulo convoca os cristãos à vigilância no combate espiritual: 'Revesti-vos de toda a armadura de Deus (panoplia tou Theou)'. Cada peça militar romana recebe correspondência teológica precisa: o cinturão da verdade, a couraça da justiça imputada e prática, o calçado do evangelho da paz, o escudo da fé contra os dardos inflamados do maligno, o capacete da certeza da salvação e a espada do Espírito, que é a palavra de Deus, tudo sustentado em constante oração.",
      "9-12": "A passagem de Efésios 6:10-18 fundamenta a guerra espiritual cristã não em agressividade humana, mas na apropriação defensiva da vitória já consumada por Cristo na Cruz. A força do guerreiro reside unicamente no poder do Senhor ('sede fortalecidos no Senhor e na força do seu poder'). A integridade moral e a dependência da Escritura garantem a vitória inabalável."
